		/** 
		 * Tests creating a new Activity.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Activity");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Activity" );

			try {            
				Activity entity = ActivityService.getActivityInstance().createActivity( generateNewEntity() );
				thePrimaryKey = entity.getActivityId();
				LOGGER.info( "-- Successfully created a Activity with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Activity. 
		 */
		public Activity testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Activity" );

			Activity entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Activity with primary key" );
			msg.append( thePrimaryKey );
			
			ActivityFetchOneSummary fetchOneSummary = new ActivityFetchOneSummary( thePrimaryKey );

			try {
				entity = ActivityService.getActivityInstance().getActivity( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Activity " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Activity.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Activity." );

			StringBuilder msg = new StringBuilder( "Failed to update a Activity : " );        
			Activity entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Activity." );

				// for use later on...
				thePrimaryKey = entity.getActivityId();

				ActivityService proxy = ActivityService.getActivityInstance();            
				proxy.updateActivity( entity );   

				LOGGER.info( "-- Successfully saved Activity - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Activity.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Activity." );

			try{
			    Activity entity = testRead(); 
				ActivityService.getActivityInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Activity with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Activity with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Activitys.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Activitys:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Activity : " );        
			List<Activity> collection  = null;

			try {
				// call the static get method on the ActivityService
				collection = ActivityService.getActivityInstance().getAllActivity();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Activity entity = null;            
					Iterator<Activity> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getActivityId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		ActivityTest
		 */
		public ActivityTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Activity
		 * 
		 * @return Activity
		 */
		protected Activity generateNewEntity() {
			Activity entity = new Activity( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),   new Date(),   new Date(),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  null,  null,  null,  null,  null,  null,  null,  ActivityType.values()[0],  ActivityStatus.values()[0],  ActivityPriority.values()[0] );
			
			return( entity );
		}

		//-----------------------------------------------------
